let javaHome: Path = Path(System.getProperty("java.home"))
let java: Path = javaHome.join("bin\\javaw.exe")
let cp: String = System.getProperty("java.class.path")
let process: Process = ProcessBuilder()
.command(java.toString(), "-cp", cp, AnsiMain.name)
.start()
let baos: ByteArrayOutputStream = ByteArrayOutputStream()
try (let `in`: InputStream = process.getInputStream()) {
let buffer: Array<Byte> = Array<Byte>(8192, item: 0)
while (true) {
let nb: Int64 = `in`.read(buffer)
if (nb > 0) {
baos.write(buffer, 0, nb)
} else {
break
}
}
}
@Expect(baos.toString().contains("test on System.out"), baos.toString())

